    let promise;
    try {
      promise = Promise.resolve().then(() => fn(...args));
    } catch (err) {
      promise = Promise.reject(err);
    }

    inProgress.set(key, promise);

    return promise.then(
      (result) => {
        inProgress.delete(key);
        cache.set(key, result);
        return result;
      },
      (err) => {
        inProgress.delete(key);
        throw err;
      }
    );
  };
}

